{noformat}const mysql = require("mysql2/promise");

const INVOICE_ROW_TABLE_NAME = "invoice_document_row";

async function main() {
    const connection = await mysql.createConnection({
        host: process.env.HOST ?? "proxysql-prelive.sqldb",
        port: process.env.PORT ?? 3306,
        user: process.env.USER,
        password: process.env.PASSWORD,
        database: process.env.DATABASE ?? "taxify_billing_document",
    });

    let rowsWithEmptyUnitPrice = await getRowsWithEmptyUnitPrice(connection);
    while (rowsWithEmptyUnitPrice?.length > 0) {
        const result = await updateUnitPriceRows(
            connection,
            rowsWithEmptyUnitPrice,
        );
        console.log(
            `Rows with ids update [${rowsWithEmptyUnitPrice.join(
                ", ",
            )}]. Number of rows updated ${JSON.stringify(result[0])}`,
        );
        rowsWithEmptyUnitPrice = await getRowsWithEmptyUnitPrice(connection);
    }
    await connection.end();
}

async function getRowsWithEmptyUnitPrice(connection) {
    const query = `        SELECT id        FROM ${INVOICE_ROW_TABLE_NAME}        WHERE unit_price IS NULL            LIMIT 500    `;

    return connection.execute(query).then(([rows]) => rows.map((row) => row.id));
}

async function updateUnitPriceRows(connection, rowsForUpdate) {
    const rowsIds = rowsForUpdate.join(", ");
    const query = `        UPDATE ${INVOICE_ROW_TABLE_NAME}        SET unit_price = Math.round((sum * 100) / quantity) / 100        WHERE unit_price IS NULL          AND id IN (${rowsIds})    `;

    return await connection.execute(query);
}

main();{noformat}

